static void print_version(void) {
    printf("b3sum 1.8.4\n");
}

static void parse_error_unexpected(const char *arg) {
    fprintf(stderr, "error: unexpected argument '%s' found\n\n", arg);
    fprintf(stderr, "  tip: to pass '%s' as a value, use '-- %s'\n\n", arg, arg);
    fprintf(stderr, "Usage: %s [OPTIONS] [FILE]...\n\n", g_prog);
    fprintf(stderr, "For more information, try '--help'.\n");
}

static void parse_error_value_required(const char *opt_display) {
    fprintf(stderr, "error: a value is required for '%s' but none was supplied\n\n", opt_display);
    fprintf(stderr, "For more information, try '--help'.\n");
}

static void parse_error_invalid_value(const char *value, const char *opt_display, const char *why) {
    fprintf(stderr, "error: invalid value '%s' for '%s': %s\n\n", value, opt_display, why);
    fprintf(stderr, "For more information, try '--help'.\n");
}

static void parse_error_duplicate(const char *opt_display) {
    fprintf(stderr, "error: the argument '%s' cannot be used multiple times\n\n", opt_display);
    fprintf(stderr, "Usage: %s [OPTIONS] [FILE]...\n\n", g_prog);
    fprintf(stderr, "For more information, try '--help'.\n");
}

static void parse_error_conflict(const char *a, const char *b, const char *usage_extra) {
    fprintf(stderr, "error: the argument '%s' cannot be used with '%s'\n\n", a, b);
    fprintf(stderr, "Usage: %s %s\n\n", g_prog, usage_extra);
    fprintf(stderr, "For more information, try '--help'.\n");
}

static void parse_error_required_check(void) {
    fprintf(stderr, "error: the following required arguments were not provided:\n");
    fprintf(stderr, "  --check\n\n");
    fprintf(stderr, "Usage: %s --check --quiet [FILE]...\n\n", g_prog);
    fprintf(stderr, "For more information, try '--help'.\n");
}

static void parse_error_required_file_for_keyed(void) {
    fprintf(stderr, "error: the following required arguments were not provided:\n");
    fprintf(stderr, "  <FILE>...\n\n");
    fprintf(stderr, "Usage: %s --keyed <FILE>...\n\n", g_prog);
    fprintf(stderr, "For more information, try '--help'.\n");
}

static int add_file(Options *opt, char *file) {
    if (opt->file_count == opt->file_cap) {
        int new_cap = opt->file_cap ? opt->file_cap * 2 : 8;
        char **new_files = (char **)realloc(opt->files, (size_t)new_cap * sizeof(char *));
        if (!new_files) return -1;
        opt->files = new_files;
        opt->file_cap = new_cap;
    }
    opt->files[opt->file_count++] = file;
    return 0;
}

static int parse_u64_value(const char *value, const char *opt_display, uint64_t *out) {
    if (value[0] == '\0') {
        parse_error_invalid_value(value, opt_display, "cannot parse integer from empty string");
        return -1;
    }
    uint64_t acc = 0;
    for (const unsigned char *p = (const unsigned char *)value; *p; p++) {
        if (*p < '0' || *p > '9') {
            parse_error_invalid_value(value, opt_display, "invalid digit found in string");
            return -1;
        }
        uint64_t digit = (uint64_t)(*p - '0');
        if (acc > (UINT64_MAX - digit) / 10u) {
            parse_error_invalid_value(value, opt_display, "number too large to fit in target type");
            return -1;
        }
        acc = acc * 10u + digit;
    }
    *out = acc;
    return 0;
}

static int take_next_value(int argc, char **argv, int *i, const char *opt_display, const char **value_out) {
    if (*i + 1 >= argc) {
        parse_error_value_required(opt_display);
        return -1;
    }
    const char *v = argv[*i + 1];
    if (v[0] == '-' && v[1] != '\0') {
        parse_error_unexpected(v);
        return -1;
    }
    (*i)++;
    *value_out = v;
    return 0;
}

static int set_bool_once(int *seen, int *field, const char *display) {
    if (*seen) {
        parse_error_duplicate(display);
        return -1;
    }
    *seen = 1;
    *field = 1;
    return 0;
}

static int parse_args(int argc, char **argv, Options *opt) {
    memset(opt, 0, sizeof(*opt));
    opt->length = 32;
    opt->seek = 0;

    int stop_opts = 0;
    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];
        if (stop_opts) {
            if (add_file(opt, arg) != 0) return -1;
            continue;
        }
        if (strcmp(arg, "--") == 0) {
            stop_opts = 1;
            continue;
        }
        if (strcmp(arg, "-") == 0 || arg[0] != '-') {
            if (add_file(opt, arg) != 0) return -1;
            continue;
        }
        if (strncmp(arg, "--", 2) == 0) {
            char *eq = strchr(arg, '=');
            size_t name_len = eq ? (size_t)(eq - arg) : strlen(arg);
            const char *val = eq ? eq + 1 : NULL;
#define LONG_IS(s) (name_len == strlen(s) && strncmp(arg, s, name_len) == 0)
            if (LONG_IS("--help")) {
                if (eq) {
                    fprintf(stderr, "error: unexpected value '%s' for '--help' found; no more were expected\n\n", val);
                    fprintf(stderr, "Usage: %s --help [FILE]...\n\n", g_prog);
                    fprintf(stderr, "For more information, try '--help'.\n");
                    return 2;
                }
                print_long_help();
                return 100;
            } else if (LONG_IS("--version")) {
                if (eq) {
                    fprintf(stderr, "error: unexpected value '%s' for '--version' found; no more were expected\n\n", val);
                    fprintf(stderr, "Usage: %s --version [FILE]...\n\n", g_prog);
                    fprintf(stderr, "For more information, try '--help'.\n");
                    return 2;
                }
                print_version();
                return 100;
            } else if (LONG_IS("--keyed")) {
                if (eq) {
                    fprintf(stderr, "error: unexpected value '%s' for '--keyed' found; no more were expected\n\n", val);
                    fprintf(stderr, "Usage: %s --keyed [FILE]...\n\n", g_prog);
                    fprintf(stderr, "For more information, try '--help'.\n");
                    return 2;
                }
                if (set_bool_once(&opt->seen_keyed, &opt->keyed, "--keyed") != 0) return 2;
            } else if (LONG_IS("--derive-key")) {
                if (opt->derive_key) {
                    parse_error_duplicate("--derive-key <CONTEXT>");
                    return 2;
                }
                if (!eq) {
                    if (take_next_value(argc, argv, &i, "--derive-key <CONTEXT>", &val) != 0) return 2;
                }
                opt->derive_key = 1;
                opt->context = (char *)val;
            } else if (LONG_IS("--length")) {
                if (opt->have_length) {
                    parse_error_duplicate("--length <LEN>");
                    return 2;
                }
                if (!eq) {
                    if (take_next_value(argc, argv, &i, "--length <LEN>", &val) != 0) return 2;
                }
                uint64_t x;
                if (parse_u64_value(val, "--length <LEN>", &x) != 0) return 2;
                opt->length = x;
                opt->have_length = 1;
            } else if (LONG_IS("--seek")) {
                if (opt->have_seek) {
                    parse_error_duplicate("--seek <SEEK>");
                    return 2;
                }
                if (!eq) {
                    if (take_next_value(argc, argv, &i, "--seek <SEEK>", &val) != 0) return 2;
                }
                uint64_t x;
                if (parse_u64_value(val, "--seek <SEEK>", &x) != 0) return 2;
                opt->seek = x;
                opt->have_seek = 1;
            } else if (LONG_IS("--num-threads")) {
                if (opt->have_num_threads) {
                    parse_error_duplicate("--num-threads <NUM>");
                    return 2;
                }
                if (!eq) {
                    if (take_next_value(argc, argv, &i, "--num-threads <NUM>", &val) != 0) return 2;
                }
                uint64_t x;
                if (parse_u64_value(val, "--num-threads <NUM>", &x) != 0) return 2;
                opt->num_threads = x;
                opt->have_num_threads = 1;
            } else if (LONG_IS("--no-mmap")) {
                if (eq) { parse_error_unexpected(arg); return 2; }
                if (set_bool_once(&opt->seen_no_mmap, &opt->no_mmap, "--no-mmap") != 0) return 2;
            } else if (LONG_IS("--no-names")) {
                if (eq) { parse_error_unexpected(arg); return 2; }
                if (set_bool_once(&opt->seen_no_names, &opt->no_names, "--no-names") != 0) return 2;
            } else if (LONG_IS("--raw")) {
                if (eq) { parse_error_unexpected(arg); return 2; }
                if (set_bool_once(&opt->seen_raw, &opt->raw, "--raw") != 0) return 2;
            } else if (LONG_IS("--tag")) {
                if (eq) { parse_error_unexpected(arg); return 2; }
                if (set_bool_once(&opt->seen_tag, &opt->tag, "--tag") != 0) return 2;
            } else if (LONG_IS("--check")) {
                if (eq) { parse_error_unexpected(arg); return 2; }
                if (set_bool_once(&opt->seen_check, &opt->check, "--check") != 0) return 2;
            } else if (LONG_IS("--quiet")) {
                if (eq) { parse_error_unexpected(arg); return 2; }
                if (set_bool_once(&opt->seen_quiet, &opt->quiet, "--quiet") != 0) return 2;
            } else {
                parse_error_unexpected(arg);
                return 2;
            }
#undef LONG_IS
            continue;
        }

        /* Short flags. Clap accepts clusters, and -l consumes the remainder as its value. */
        size_t arglen = strlen(arg);
        for (size_t pos = 1; pos < arglen; pos++) {
            char ch = arg[pos];
            if (ch == 'h') {
                print_short_help();
                return 100;
            } else if (ch == 'V') {
                print_version();
                return 100;
            } else if (ch == 'c') {
                if (set_bool_once(&opt->seen_check, &opt->check, "--check") != 0) return 2;
            } else if (ch == 'l') {
                if (opt->have_length) {
                    parse_error_duplicate("--length <LEN>");
                    return 2;
                }
                const char *val = NULL;
                if (pos + 1 < arglen) {
                    val = arg + pos + 1;
                    if (val[0] == '=') val++;
                    pos = arglen;
                } else {
                    if (take_next_value(argc, argv, &i, "--length <LEN>", &val) != 0) return 2;
                }
                uint64_t x;
                if (parse_u64_value(val, "--length <LEN>", &x) != 0) return 2;
                opt->length = x;
                opt->have_length = 1;
                break;
            } else {
                parse_error_unexpected(arg);
                return 2;
            }
        }
    }

    if (opt->keyed && opt->derive_key) {
        parse_error_conflict("--keyed", "--derive-key <CONTEXT>", "--keyed <FILE>...");
        return 2;
    }
    if (opt->quiet && !opt->check) {
        parse_error_required_check();
        return 2;
    }
    if (opt->keyed && opt->file_count == 0) {
        parse_error_required_file_for_keyed();
        return 2;
    }
    if (opt->check) {
        if (opt->have_length) {
            parse_error_conflict("--check", "--length <LEN>", "--check [FILE]...");
            return 2;
        }
        if (opt->keyed) {
            parse_error_conflict("--check", "--keyed", "--check [FILE]...");
            return 2;
        }
        if (opt->derive_key) {
            parse_error_conflict("--check", "--derive-key <CONTEXT>", "--check [FILE]...");
            return 2;
        }
        if (opt->raw) {
            parse_error_conflict("--check", "--raw", "--check [FILE]...");
            return 2;
        }
        if (opt->no_names) {
            parse_error_conflict("--check", "--no-names", "--check [FILE]...");
            return 2;
        }
        if (opt->tag) {
            parse_error_conflict("--check", "--tag", "--check [FILE]...");
            return 2;
        }
    }
    return 0;
}

static void print_os_error_for_file(const char *path, int err) {
    fprintf(stderr, "b3sum: %s: %s (os error %d)\n", path, strerror(err), err);
}

static void print_error_os_only(int err) {
    fprintf(stderr, "Error: %s (os error %d)\n", strerror(err), err);
}

static int filename_needs_escape(const char *s) {
    for (; *s; s++) {
        if (*s == '\\' || *s == '\n') return 1;
    }
    return 0;
}

static void fprint_escaped_filename(FILE *f, const char *s) {
    for (; *s; s++) {
        if (*s == '\\') fputs("\\\\", f);
        else if (*s == '\n') fputs("\\n", f);
        else fputc((unsigned char)*s, f);
    }
}

static void print_name_for_status(const char *name) {
    if (filename_needs_escape(name)) fputc('\\', stdout);
    fprint_escaped_filename(stdout, name);
}

static void bytes_to_hex(const uint8_t *bytes, uint64_t len, FILE *f) {
    static const char HEX[] = "0123456789abcdef";
    for (uint64_t i = 0; i < len; i++) {
        fputc(HEX[bytes[i] >> 4], f);
        fputc(HEX[bytes[i] & 0x0F], f);
    }
}

static void print_hash_line(const Options *opt, const char *name, const uint8_t *hash) {
    if (opt->raw) {
        if (opt->length > 0) fwrite(hash, 1, (size_t)opt->length, stdout);
        return;
    }
    if (opt->no_names) {
        bytes_to_hex(hash, opt->length, stdout);
        fputc('\n', stdout);
        return;
    }
    int esc = filename_needs_escape(name);
    if (opt->tag) {
        if (esc) fputc('\\', stdout);
        fputs("BLAKE3 (", stdout);
        fprint_escaped_filename(stdout, name);
        fputs(") = ", stdout);
        bytes_to_hex(hash, opt->length, stdout);
        fputc('\n', stdout);
    } else {
        if (esc) fputc('\\', stdout);
        bytes_to_hex(hash, opt->length, stdout);
        fputs("  ", stdout);
        fprint_escaped_filename(stdout, name);
        fputc('\n', stdout);
    }
}

static int compute_named_hash(const char *path, int use_stdin, const Options *opt,
                              const uint32_t key_words[8], uint32_t flags, uint8_t *hash) {
    FILE *f = NULL;
    if (use_stdin) {
        f = stdin;
    } else {
        f = fopen(path, "rb");
        if (!f) return errno ? errno : EIO;
    }
    int ret = hash_file_stream(f, key_words, flags, opt->seek, opt->length, hash);
    int saved = errno;
    if (!use_stdin) fclose(f);
    if (ret != 0) return saved ? saved : EIO;
    return 0;
}

static int read_key_from_stdin(uint32_t key_words[8]) {
    uint8_t key[33];
    size_t got = 0;
    while (got < 33) {
        size_t n = fread(key + got, 1, 33 - got, stdin);
        if (n > 0) {
            got += n;
            continue;
        }
        if (ferror(stdin)) {
            int err = errno ? errno : EIO;
            fprintf(stderr, "Error: %s (os error %d)\n", strerror(err), err);
            return -1;
        }
        break;
    }
    if (got < 32) {
        fprintf(stderr, "Error: expected 32 key bytes from stdin, found %zu\n", got);
        return -1;
    }
    if (got > 32) {
        fprintf(stderr, "Error: read more than 32 key bytes from stdin\n");
        return -1;
    }
    key_bytes_to_words(key, key_words);
    return 0;
}

static int run_hash_mode(const Options *opt) {
    if (opt->raw && opt->file_count > 1) {
        fprintf(stderr, "Error: Only one filename can be provided when using --raw\n");
        return 1;
    }

    uint32_t key_words[8];
    uint32_t flags = 0;
    if (opt->keyed) {
        if (read_key_from_stdin(key_words) != 0) return 1;
        flags = KEYED_HASH;
    } else if (opt->derive_key) {
        if (derive_key_words_from_context(opt->context, key_words) != 0) {
            fprintf(stderr, "Error: failed to derive key\n");
            return 1;
        }
        flags = DERIVE_KEY_MATERIAL;
    } else {
        default_key(key_words);
    }

    int status = 0;
    int count = opt->file_count;
    if (count == 0) count = 1;
    for (int idx = 0; idx < count; idx++) {
        const char *path = (opt->file_count == 0) ? "-" : opt->files[idx];
        int use_stdin = (strcmp(path, "-") == 0);
        if (opt->keyed && use_stdin) {
            fprintf(stderr, "b3sum: -: Cannot open `-' in keyed mode\n");
            status = 1;
            continue;
        }
        uint8_t *hash = NULL;
        if (opt->length > 0) {
            hash = (uint8_t *)malloc((size_t)opt->length);
            if (!hash) {
                fprintf(stderr, "Error: memory allocation failed\n");
                return 1;
            }
        } else {
            hash = (uint8_t *)malloc(1);
            if (!hash) return 1;
        }
        int err = compute_named_hash(path, use_stdin, opt, key_words, flags, hash);
        if (err != 0) {
            print_os_error_for_file(path, err);
            status = 1;
            free(hash);
            continue;
        }
        print_hash_line(opt, path, hash);
        free(hash);
    }
    return status;
}

static int is_lower_hex_char(char c) {
    return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f');
}

static int hex_nibble(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return 10 + c - 'a';
    return -1;
}

static int decode_hex_32(const char *hex, uint8_t out[32], const char **err_msg) {
    size_t len = strlen(hex);
    if (len != 64) {
        *err_msg = "Invalid hash length";
        return -1;
    }
    for (size_t i = 0; i < 64; i++) {
        if (!is_lower_hex_char(hex[i])) {
            *err_msg = "Invalid hex";
            return -1;
        }
    }
    for (int i = 0; i < 32; i++) {
        out[i] = (uint8_t)((hex_nibble(hex[2 * i]) << 4) | hex_nibble(hex[2 * i + 1]));
    }
    return 0;
}

static char *xstrndup(const char *s, size_t n) {
    char *p = (char *)malloc(n + 1);
    if (!p) return NULL;
    memcpy(p, s, n);
    p[n] = '\0';
    return p;
}

static char *unescape_filename(const char *s, const char **err_msg) {
    size_t len = strlen(s);
    char *out = (char *)malloc(len + 1);
    if (!out) {
        *err_msg = "memory allocation failed";
        return NULL;
    }
    size_t j = 0;
    for (size_t i = 0; i < len; i++) {
        if (s[i] == '\\') {
            i++;
            if (i >= len) {
                free(out);
                *err_msg = "Invalid backslash escape";
                return NULL;
            }
            if (s[i] == '\\') out[j++] = '\\';
            else if (s[i] == 'n') out[j++] = '\n';
            else {
                free(out);
                *err_msg = "Invalid backslash escape";
                return NULL;
            }
        } else {
            out[j++] = s[i];
        }
    }
    out[j] = '\0';
    return out;
}

typedef struct {
    char *filename;
    char *hex;
} CheckLine;

static int parse_check_line(char *line, CheckLine *parsed, const char **err_msg) {
    parsed->filename = NULL;
    parsed->hex = NULL;
    size_t line_len = strlen(line);
    if (line_len == 0) {
        *err_msg = "Empty line";
        return -1;
    }
    int escaped = 0;
    if (line[0] == '\\') {
        escaped = 1;
        line++;
        line_len--;
        if (line_len == 0) {
            *err_msg = "Invalid check line format";
            return -1;
        }
    }

    if (strncmp(line, "BLAKE3 (", 8) == 0) {
        char *delim = NULL;
        char *scan = line + 8;
        while ((scan = strstr(scan, ") = ")) != NULL) {
            delim = scan;
            scan += 4;
        }
        if (!delim) {
            *err_msg = "Invalid check line format";
            return -1;
        }
        char *fname_raw = xstrndup(line + 8, (size_t)(delim - (line + 8)));
        if (!fname_raw) return -1;
        char *hex_raw = strdup(delim + 4);
        if (!hex_raw) { free(fname_raw); return -1; }
        char *fname = fname_raw;
        if (escaped) {
            fname = unescape_filename(fname_raw, err_msg);
            free(fname_raw);
            if (!fname) { free(hex_raw); return -1; }
        }
        parsed->filename = fname;
        parsed->hex = hex_raw;
        return 0;
    }

    char *sep = strstr(line, "  ");
    if (!sep) {
        *err_msg = "Invalid check line format";
        return -1;
    }
    char *hex_raw = xstrndup(line, (size_t)(sep - line));
    char *fname_raw = strdup(sep + 2);
    if (!hex_raw || !fname_raw) {
        free(hex_raw);
        free(fname_raw);
        return -1;
    }
    char *fname = fname_raw;
    if (escaped) {
        fname = unescape_filename(fname_raw, err_msg);
        free(fname_raw);
        if (!fname) { free(hex_raw); return -1; }
    }
    parsed->filename = fname;
    parsed->hex = hex_raw;
    return 0;
}

static void free_check_line(CheckLine *line) {
    free(line->filename);
    free(line->hex);
    line->filename = NULL;
    line->hex = NULL;
}

static int compute_check_hash_for_file(const char *path, uint64_t seek, uint8_t out[32], int *err_out) {
    uint32_t key_words[8];
    default_key(key_words);
    Options tmp;
    memset(&tmp, 0, sizeof(tmp));
    tmp.length = 32;
    tmp.seek = seek;
    FILE *f = fopen(path, "rb");
    if (!f) {
        *err_out = errno ? errno : EIO;
        return -1;
    }
    int ret = hash_file_stream(f, key_words, 0, seek, 32, out);
    int saved = errno;
    fclose(f);
    if (ret != 0) {
        *err_out = saved ? saved : EIO;
        return -1;
    }
    return 0;
}

static int check_one_stream(FILE *f, const Options *opt, uint64_t *failures) {
    char *line = NULL;
    size_t cap = 0;
    ssize_t nread;
    while ((nread = getline(&line, &cap, f)) != -1) {
        while (nread > 0 && (line[nread - 1] == '\n' || line[nread - 1] == '\r')) {
            line[--nread] = '\0';
            if (nread > 0 && line[nread - 1] == '\r') {
                line[--nread] = '\0';
            }
        }
        CheckLine parsed;
        const char *err_msg = NULL;
        if (parse_check_line(line, &parsed, &err_msg) != 0) {
            fprintf(stderr, "b3sum: %s\n", err_msg ? err_msg : "Invalid check line format");
            (*failures)++;
            continue;
        }
        uint8_t expected[32];
        if (decode_hex_32(parsed.hex, expected, &err_msg) != 0) {
            fprintf(stderr, "b3sum: %s\n", err_msg);
            (*failures)++;
            free_check_line(&parsed);
            continue;
        }
        uint8_t actual[32];
        int os_err = 0;
        if (compute_check_hash_for_file(parsed.filename, opt->seek, actual, &os_err) != 0) {
            print_name_for_status(parsed.filename);
            printf(": FAILED (%s (os error %d))\n", strerror(os_err), os_err);
            (*failures)++;
            free_check_line(&parsed);
            continue;
        }
        if (memcmp(expected, actual, 32) == 0) {
            if (!opt->quiet) {
                print_name_for_status(parsed.filename);
                printf(": OK\n");
            }
        } else {
            print_name_for_status(parsed.filename);
            printf(": FAILED\n");
            (*failures)++;
        }
        free_check_line(&parsed);
    }
    free(line);
    if (ferror(f)) return -1;
    return 0;
}

static int run_check_mode(const Options *opt) {
    uint64_t failures = 0;
    int count = opt->file_count;
    if (count == 0) count = 1;
    for (int i = 0; i < count; i++) {
        const char *path = (opt->file_count == 0) ? "-" : opt->files[i];
        FILE *f = NULL;
        int use_stdin = strcmp(path, "-") == 0;
        if (use_stdin) {
            f = stdin;
        } else {
            f = fopen(path, "rb");
            if (!f) {
                print_error_os_only(errno ? errno : EIO);
                return 1;
            }
        }
        if (check_one_stream(f, opt, &failures) != 0) {
            int err = errno ? errno : EIO;
            if (!use_stdin) fclose(f);
            print_error_os_only(err);
            return 1;
        }
        if (!use_stdin) fclose(f);
    }
    if (failures > 0) {
        fprintf(stderr, "b3sum: WARNING: %llu computed checksum%s did NOT match\n",
                (unsigned long long)failures, failures == 1 ? "" : "s");
        return 1;
    }
    return 0;
}

int main(int argc, char **argv) {
    g_prog = base_name(argv[0]);
    Options opt;
    int pr = parse_args(argc, argv, &opt);
    if (pr == 100) {
        free(opt.files);
        return 0;
    }
    if (pr != 0) {
        free(opt.files);
        return pr == 2 ? 2 : 1;
    }
    int ret = opt.check ? run_check_mode(&opt) : run_hash_mode(&opt);
    free(opt.files);
    return ret;
}
