static uint32_t rotr32(uint32_t x, unsigned n) {
    return (x >> n) | (x << (32 - n));
}

static uint32_t load32(const uint8_t *p) {
    return ((uint32_t)p[0]) | ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static void store32(uint8_t *p, uint32_t x) {
    p[0] = (uint8_t)x;
    p[1] = (uint8_t)(x >> 8);
    p[2] = (uint8_t)(x >> 16);
    p[3] = (uint8_t)(x >> 24);
}

static void bytes_to_words(const uint8_t block[64], uint32_t words[16]) {
    for (int i = 0; i < 16; i++) {
        words[i] = load32(block + 4 * i);
    }
}

static void words_to_bytes(const uint32_t words[16], uint8_t out[64]) {
    for (int i = 0; i < 16; i++) {
        store32(out + 4 * i, words[i]);
    }
}

static void g(uint32_t state[16], int a, int b, int c, int d, uint32_t mx, uint32_t my) {
    state[a] = state[a] + state[b] + mx;
    state[d] = rotr32(state[d] ^ state[a], 16);
    state[c] = state[c] + state[d];
    state[b] = rotr32(state[b] ^ state[c], 12);
    state[a] = state[a] + state[b] + my;
    state[d] = rotr32(state[d] ^ state[a], 8);
    state[c] = state[c] + state[d];
    state[b] = rotr32(state[b] ^ state[c], 7);
}

static void round_fn(uint32_t state[16], const uint32_t m[16], int round) {
    const uint8_t *s = MSG_SCHEDULE[round];
    g(state, 0, 4, 8, 12, m[s[0]], m[s[1]]);
    g(state, 1, 5, 9, 13, m[s[2]], m[s[3]]);
    g(state, 2, 6, 10, 14, m[s[4]], m[s[5]]);
    g(state, 3, 7, 11, 15, m[s[6]], m[s[7]]);
    g(state, 0, 5, 10, 15, m[s[8]], m[s[9]]);
    g(state, 1, 6, 11, 12, m[s[10]], m[s[11]]);
    g(state, 2, 7, 8, 13, m[s[12]], m[s[13]]);
    g(state, 3, 4, 9, 14, m[s[14]], m[s[15]]);
}

static void compress(const uint32_t cv[8], const uint32_t block_words[16],
                     uint64_t counter, uint32_t block_len, uint32_t flags,
                     uint32_t out[16]) {
    uint32_t state[16];
    for (int i = 0; i < 8; i++) state[i] = cv[i];
    state[8] = IV[0];
    state[9] = IV[1];
    state[10] = IV[2];
    state[11] = IV[3];
    state[12] = (uint32_t)counter;
    state[13] = (uint32_t)(counter >> 32);
    state[14] = block_len;
    state[15] = flags;

    for (int r = 0; r < 7; r++) {
        round_fn(state, block_words, r);
    }

    for (int i = 0; i < 8; i++) {
        out[i] = state[i] ^ state[i + 8];
        out[i + 8] = state[i + 8] ^ cv[i];
    }
}

static void output_chaining_value(const Output *out, uint32_t cv[8]) {
    uint32_t words[16];
    compress(out->input_cv, out->block_words, out->counter, out->block_len, out->flags, words);
    for (int i = 0; i < 8; i++) cv[i] = words[i];
}

static void chunk_output(const uint8_t *chunk, size_t chunk_len, uint64_t chunk_counter,
                         const uint32_t key_words[8], uint32_t flags, Output *out) {
    uint32_t cv[8];
    for (int i = 0; i < 8; i++) cv[i] = key_words[i];

    size_t offset = 0;
    int block_index = 0;
    while (chunk_len - offset > BLAKE3_BLOCK_LEN) {
        uint8_t block[64];
        memcpy(block, chunk + offset, 64);
        uint32_t block_words[16];
        bytes_to_words(block, block_words);
        uint32_t block_flags = flags;
        if (block_index == 0) block_flags |= CHUNK_START;
        uint32_t words[16];
        compress(cv, block_words, chunk_counter, 64, block_flags, words);
        for (int i = 0; i < 8; i++) cv[i] = words[i];
        offset += 64;
        block_index++;
    }

    uint8_t block[64];
    memset(block, 0, sizeof(block));
    size_t last_len = chunk_len - offset;
    if (last_len > 0) memcpy(block, chunk + offset, last_len);
    for (int i = 0; i < 8; i++) out->input_cv[i] = cv[i];
    bytes_to_words(block, out->block_words);
    out->counter = chunk_counter;
    out->block_len = (uint32_t)last_len;
    out->flags = flags | CHUNK_END;
    if (block_index == 0) out->flags |= CHUNK_START;
}

static void parent_output(const uint32_t left_cv[8], const uint32_t right_cv[8],
                          const uint32_t key_words[8], uint32_t flags, Output *out) {
    for (int i = 0; i < 8; i++) out->input_cv[i] = key_words[i];
    for (int i = 0; i < 8; i++) out->block_words[i] = left_cv[i];
    for (int i = 0; i < 8; i++) out->block_words[i + 8] = right_cv[i];
    out->counter = 0;
    out->block_len = 64;
    out->flags = flags | PARENT;
}

static void parent_cv(const uint32_t left_cv[8], const uint32_t right_cv[8],
                      const uint32_t key_words[8], uint32_t flags, uint32_t cv[8]) {
    Output out;
    parent_output(left_cv, right_cv, key_words, flags, &out);
    output_chaining_value(&out, cv);
}

static void add_chunk_cv(CvStack *stack, const uint32_t new_cv_in[8], uint64_t total_chunks,
                         const uint32_t key_words[8], uint32_t flags) {
    uint32_t new_cv[8];
    for (int i = 0; i < 8; i++) new_cv[i] = new_cv_in[i];
    while ((total_chunks & 1u) == 0) {
        uint32_t combined[8];
        if (stack->len == 0) break; /* Defensive; should not happen. */
        parent_cv(stack->cvs[stack->len - 1], new_cv, key_words, flags, combined);
        stack->len--;
        for (int i = 0; i < 8; i++) new_cv[i] = combined[i];
        total_chunks >>= 1;
    }
    if (stack->len < 64) {
        for (int i = 0; i < 8; i++) stack->cvs[stack->len][i] = new_cv[i];
        stack->len++;
    }
}

static void root_output_bytes(const Output *root, uint64_t seek, uint64_t len, uint8_t *out_bytes) {
    uint64_t block_counter = seek / 64;
    size_t offset = (size_t)(seek % 64);
    uint64_t produced = 0;
    while (produced < len) {
        uint32_t words[16];
        uint8_t block[64];
        compress(root->input_cv, root->block_words, block_counter, root->block_len,
                 root->flags | ROOT, words);
        words_to_bytes(words, block);
        size_t take = 64 - offset;
        if (take > len - produced) take = (size_t)(len - produced);
        memcpy(out_bytes + produced, block + offset, take);
        produced += take;
        block_counter++;
        offset = 0;
    }
}

static int read_chunk(FILE *f, uint8_t buf[1024], size_t *len_out) {
    size_t got = 0;
    while (got < BLAKE3_CHUNK_LEN) {
        size_t n = fread(buf + got, 1, BLAKE3_CHUNK_LEN - got, f);
        if (n > 0) {
            got += n;
            continue;
        }
        if (ferror(f)) return -1;
        break; /* EOF */
    }
    *len_out = got;
    return 0;
}

static int hash_file_stream(FILE *f, const uint32_t key_words[8], uint32_t flags,
                            uint64_t seek, uint64_t out_len, uint8_t *out_hash) {
    uint8_t cur[1024];
    uint8_t next[1024];
    size_t cur_len = 0;
    if (read_chunk(f, cur, &cur_len) != 0) return -1;

    CvStack stack;
    stack.len = 0;
    uint64_t chunk_index = 0;

    while (cur_len == BLAKE3_CHUNK_LEN) {
        size_t next_len = 0;
        if (read_chunk(f, next, &next_len) != 0) return -1;
        if (next_len == 0) {
            break; /* current full chunk is the final chunk */
        }
        Output out;
        uint32_t cv[8];
        chunk_output(cur, cur_len, chunk_index, key_words, flags, &out);
        output_chaining_value(&out, cv);
        add_chunk_cv(&stack, cv, chunk_index + 1, key_words, flags);
        memcpy(cur, next, next_len);
        cur_len = next_len;
        chunk_index++;
    }

    Output root;
    chunk_output(cur, cur_len, chunk_index, key_words, flags, &root);
    while (stack.len > 0) {
        uint32_t right_cv[8];
        output_chaining_value(&root, right_cv);
        Output parent;
        parent_output(stack.cvs[stack.len - 1], right_cv, key_words, flags, &parent);
        stack.len--;
        root = parent;
    }
    root_output_bytes(&root, seek, out_len, out_hash);
    return 0;
}

static void default_key(uint32_t key_words[8]) {
    for (int i = 0; i < 8; i++) key_words[i] = IV[i];
}

static void key_bytes_to_words(const uint8_t key[32], uint32_t key_words[8]) {
    for (int i = 0; i < 8; i++) key_words[i] = load32(key + 4 * i);
}

static int hash_bytes_once(const uint8_t *input, size_t input_len, const uint32_t key_words[8],
                           uint32_t flags, uint8_t out[32]) {
    /* Used only for the context string; it may be longer than one chunk, so use fmemopen if available. */
    FILE *f = fmemopen((void *)input, input_len, "rb");
    if (!f) return -1;
    int ret = hash_file_stream(f, key_words, flags, 0, 32, out);
    fclose(f);
    return ret;
}

static int derive_key_words_from_context(const char *context, uint32_t out_key_words[8]) {
    uint32_t context_key[8];
    default_key(context_key);
    uint8_t context_hash[32];
    if (hash_bytes_once((const uint8_t *)context, strlen(context), context_key,
                        DERIVE_KEY_CONTEXT, context_hash) != 0) {
        return -1;
    }
    key_bytes_to_words(context_hash, out_key_words);
    return 0;
}

static const char *base_name(const char *s) {
    const char *slash = strrchr(s, '/');
    return slash ? slash + 1 : s;
}

